151	  /**
152	   * Bloqueante: espera a que la síntesis termine antes de devolver nada. Usado por {@code /api/ask}
153	   * y Teams — siempre con {@link Consultar.Preferencias#POR_DEFECTO}, porque ninguno de los dos
154	   * tiene cómo pedirle a la persona que elija algo a mitad de camino.
155	   */
156	  EjecucionPipeline ejecutar(Pregunta pregunta, ProyectoId proyecto, Filtros filtros) {
157	    boolean cupoAdquirido = cupoConsultas.tryAcquire();
158	    try {
159	      PreSintesis pre =
160	          cupoAdquirido
161	              ? prepararHastaContexto(
162	                  pregunta, proyecto, filtros, Consultar.Preferencias.POR_DEFECTO.reformulacion())
163	              : respuestaServidorOcupado();
164	
165	      // Etapa 6: sintesis en streaming, coleccionada aqui porque este metodo
166	      // devuelve una respuesta completa, no un Flux.
167	      String textoRespuesta =
168	          sintetizarBloqueante(pregunta, pre, Consultar.Preferencias.POR_DEFECTO.idioma());
169	
170	      long latenciaMs = (System.nanoTime() - pre.inicioNanos()) / 1_000_000;
171	      // advertencias queda vacio a proposito: el prompt de sintesis exige señalar
172	      // contradicciones EN el texto de la respuesta (con [n] y prosa), no en un
173	      // campo estructurado aparte -- eso pediria una segunda llamada al LLM solo
174	      // para separar "respuesta" de "advertencia", en contra de que la sintesis
175	      // sea en streaming.
176	      Respuesta respuesta =
177	          new Respuesta(
178	              textoRespuesta, pre.citas(), List.of(), latenciaMs, pre.consultaReformulada());
179	
180	      // Etapa 7: registrar.
181	      long queryLogId =
182	          queryLog.registrar(
183	              pregunta.texto(),
184	              proyecto.valor(),
185	              pre.plan(),
186	              pre.ejecuciones(),
187	              pre.fragmentos(),
188	              textoRespuesta,
189	              pre.citas(),
190	              latenciaMs);
191	
192	      return new EjecucionPipeline(
193	          pre.plan(), pre.ejecuciones(), pre.fragmentos(), respuesta, queryLogId);
194	    } finally {
195	      if (cupoAdquirido) {
196	        cupoConsultas.release();
197	      }
198	    }
199	  }
