201	  /**
202	   * En streaming: las citas de la etapa 5 vuelven de inmediato; el texto de la etapa 6 llega token
203	   * a token. El registro de la etapa 7 ocurre cuando el {@link Flux} completa, no antes — por eso
204	   * acumula el texto en un {@link StringBuilder} con {@code doOnNext} en vez de esperar a que el
205	   * llamador termine de consumirlo.
206	   */
207	  Consultar.RespuestaEnStreaming ejecutarEnStreaming(
208	      Pregunta pregunta,
209	      ProyectoId proyecto,
210	      Filtros filtros,
211	      Long conversacionId,
212	      Consultar.Preferencias preferencias) {
213	    // Antes que nada: si esta pagina se recarga al toque de preguntar, que
214	    // ya haya algo que encontrar via StreamsEnCursoRepositorio.buscar().
215	    if (conversacionId != null) {
216	      streamsEnCurso.iniciar(conversacionId, pregunta.texto(), proyecto.valor());
217	    }
218	
219	    boolean cupoAdquirido = cupoConsultas.tryAcquire();
220	    PreSintesis pre =
221	        cupoAdquirido
222	            ? prepararHastaContexto(pregunta, proyecto, filtros, preferencias.reformulacion())
223	            : respuestaServidorOcupado();
224	
225	    // Modo Proponer y la busqueda original no alcanzo: no hay nada que
226	    // sintetizar todavia. Se devuelven las alternativas y se suelta todo lo
227	    // que la consulta tenia tomado -- el cupo (no hay Flux cuyo doFinally lo
228	    // libere) y la fila de streams_en_curso (no hay respuesta que reconectar;
229	    // ver StreamsEnCursoRepositorio.descartar). Nada va a query_log: no se
230	    // respondio nada.
231	    if (!pre.reformulacionesPropuestas().isEmpty()) {
232	      if (cupoAdquirido) {
233	        cupoConsultas.release();
234	      }
235	      if (conversacionId != null) {
236	        streamsEnCurso.descartar(conversacionId);
237	      }
238	      return new Consultar.RespuestaEnStreaming(
239	          List.of(), Flux.empty(), null, Mono.empty(), pre.reformulacionesPropuestas());
240	    }
241	
242	    if (conversacionId != null) {
243	      streamsEnCurso.actualizarCitas(conversacionId, pre.citas(), pre.consultaReformulada());
244	    }
245	
246	    StringBuilder acumulado = new StringBuilder();
247	    // Se llena dentro del doOnComplete de abajo, cuando queryLog.registrar(...)
248	    // ya devolvio el id -- para TODO camino que complete, incluido "servidor
249	    // ocupado"/"sin informacion" (esos tambien escriben una fila real en
250	    // query_log). Queda en null si el Flux termina en error o se cancela: ahi
251	    // nunca se llega a escribir en query_log, no hay id que dar.
252	    AtomicReference<Long> queryLogIdHolder = new AtomicReference<>();
253	    Flux<String> textoBase =
254	        pre.respuestaFija() != null
255	            ? Flux.just(pre.respuestaFija())
256	            : sintetizador.sintetizar(pregunta.texto(), pre.contexto(), preferencias.idioma());
257	    Flux<String> texto =
258	        textoBase
259	            .doOnNext(acumulado::append)
260	            .doOnComplete(
261	                () -> {
262	                  long latenciaMs = (System.nanoTime() - pre.inicioNanos()) / 1_000_000;
263	                  long queryLogId =
264	                      queryLog.registrar(
265	                          pregunta.texto(),
266	                          proyecto.valor(),
267	                          pre.plan(),
268	                          pre.ejecuciones(),
269	                          pre.fragmentos(),
270	                          acumulado.toString(),
271	                          pre.citas(),
272	                          latenciaMs);
273	                  queryLogIdHolder.set(queryLogId);
274	                })
275	            // El cupo cubre TODA la consulta, no solo prepararHastaContexto: la
276	            // sintesis tambien le pide tokens a Ollama. Se libera aca, cuando el
277	            // Flux de verdad termina (completa, falla o el cliente se desconecta),
278	            // no antes -- doFinally cubre las tres formas de terminar. Mismo
279	            // razonamiento para dejar el resultado final en streams_en_curso: pasa
280	            // lo mismo haya o no alguien todavia escuchando del otro lado.
281	            .doFinally(
282	                signal -> {
283	                  if (cupoAdquirido) {
284	                    cupoConsultas.release();
285	                  }
286	                  if (conversacionId != null) {
287	                    String estadoFinal = signal == SignalType.ON_COMPLETE ? "completo" : "error";
288	                    streamsEnCurso.finalizar(
289	                        conversacionId, estadoFinal, acumulado.toString(), queryLogIdHolder.get());
290	                  }
291	                });
292	
293	    // Mono.fromSupplier, no un valor ya calculado: se lee recien cuando alguien
294	    // lo suscribe (ChatController lo hace despues de agotar `texto` dentro del
295	    // mismo Flux.concat), momento en el que el doOnComplete de arriba ya corrio
296	    // y el holder tiene el id real.
297	    Mono<Long> queryLogId = Mono.fromSupplier(queryLogIdHolder::get);
298	    return new Consultar.RespuestaEnStreaming(
299	        pre.citas(), texto, pre.consultaReformulada(), queryLogId, List.of());
300	  }
