322	  private String sintetizarBloqueante(Pregunta pregunta, PreSintesis pre, IdiomaRespuesta idioma) {
323	    if (pre.respuestaFija() != null) {
324	      return pre.respuestaFija();
325	    }
326	    String texto =
327	        sintetizador
328	            .sintetizar(pregunta.texto(), pre.contexto(), idioma)
329	            .collectList()
330	            .map(partes -> String.join("", partes))
331	            .block();
332	    return texto == null ? "" : texto;
333	  }
