335	  private PreSintesis prepararHastaContexto(
336	      Pregunta pregunta,
337	      ProyectoId proyecto,
338	      Filtros filtros,
339	      Consultar.ModoReformulacion modoReformulacion) {
340	    long inicio = System.nanoTime();
341	    List<Long> documentosPermitidos = filtros.documentosPermitidos();
342	
343	    // Etapa 1: planificar -- siempre sobre la pregunta original, aunque la
344	    // busqueda vaya con otro texto: el plan elige herramientas segun de que
345	    // trata la pregunta, y eso no cambia con la reformulacion.
346	    PlanDeHerramientas plan = planificador.planificar(pregunta.texto(), catalogo.descripciones());
347	
348	    // Con Elegida, la persona ya decidio con que texto buscar (puede ser la
349	    // propia pregunta, si prefirio no reformular): se busca con eso y no se
350	    // vuelve a pasar por el Reformulador -- si no, su eleccion quedaria pisada
351	    // en silencio por una reformulacion automatica.
352	    String consultaBusqueda = pregunta.texto();
353	    String consultaReformuladaParaMostrar = null;
354	    if (modoReformulacion instanceof Consultar.ModoReformulacion.Elegida elegida) {
355	      consultaBusqueda = elegida.consultaDeBusqueda();
356	      if (!consultaBusqueda.strip().equalsIgnoreCase(pregunta.texto().strip())) {
357	        consultaReformuladaParaMostrar = consultaBusqueda;
358	      }
359	    }
360	
361	    // Etapas 2-3: ejecutar herramientas en paralelo, con fallas aisladas por
362	    // herramienta.
363	    List<Executor.EjecucionHerramienta> ejecuciones =
364	        executor.ejecutar(plan.herramientas(), consultaBusqueda, proyecto, documentosPermitidos);
365	
366	    // Etapa 4: fusionar y deduplicar entre herramientas.
367	    List<Fragmento> fragmentos =
368	        FusionDeHerramientas.combinar(
369	            ejecuciones.stream().map(Executor.EjecucionHerramienta::fragmentos).toList(),
370	            maxFragmentosContexto);
371	
372	    // ADR-0008: puerta de relevancia antes de expandir contexto y sintetizar.
373	    // El score del cross-encoder decide los casos claros sin gastar una
374	    // llamada al LLM; la zona ambigua se manda a VerificadorGrounding en vez
375	    // de confiar en que el propio sintetizador se autocensure.
376	    long chunksProyecto = herramientasRepo.contarChunks(proyecto.valor());
377	    UmbralRelevancia.Resultado umbral =
378	        UmbralRelevancia.evaluar(fragmentos, chunksProyecto, umbralRelevancia);
379	
380	    // Reformula la consulta de busqueda SOLO cuando la busqueda con la pregunta tal cual
381	    // no llego a SUFICIENTE -- reformular siempre, incluso en las preguntas que ya
382	    // buscaban bien, sumaba una llamada al LLM de mas en cada pregunta sin necesidad
383	    // (hallazgos 70-71 de la investigacion de VRAM y modelo LLM confirmaron que ayuda en
384	    // el caso dificil sin romper el caso facil, pero median el costo de la llamada
385	    // incondicional). Cubre tanto INSUFICIENTE (el caso que motivo el componente, ver
386	    // hallazgo 63: "autoboxing" vs. "boxing conversion") como AMBIGUO -- en ambos el score
387	    // ya senala que el texto original no encontro un candidato fuerte.
388	    boolean puedeReformular =
389	        !(modoReformulacion instanceof Consultar.ModoReformulacion.Elegida)
390	            && umbral.decision() != UmbralRelevancia.Decision.SUFICIENTE;
391	    if (puedeReformular) {
392	      // Los fragmentos de la primera ronda, aunque no alcancen, ya son texto REAL
393	      // de la fuente: le muestran al Reformulador con que palabras y en que
394	      // idioma esta escrita, en vez de dejarlo adivinar (ver Reformulador).
395	      Reformulador.Reformulacion reformulacion =
396	          reformulador.reformular(pregunta.texto(), pistasDelCorpus(fragmentos));
397	      if (modoReformulacion instanceof Consultar.ModoReformulacion.Proponer
398	          && reformulacion.alternativas().size() >= MIN_ALTERNATIVAS_PARA_ELEGIR) {
399	        // La persona elige: se corta aca, sin gastar la segunda ronda de
400	        // herramientas ni la sintesis. Con una sola alternativa no hay nada
401	        // que elegir y se responde de inmediato por el camino automatico de
402	        // abajo (pedido explicito de producto); sin ninguna, tambien.
403	        return new PreSintesis(
404	            plan,
405	            ejecuciones,
406	            fragmentos,
407	            List.of(),
408	            "",
409	            null,
410	            null,
411	            reformulacion.alternativas(),
412	            inicio);
413	      }
414	      if (reformulacion.reformulada()) {
415	        List<Executor.EjecucionHerramienta> reejecuciones =
416	            executor.ejecutar(
417	                plan.herramientas(), reformulacion.textoBusqueda(), proyecto, documentosPermitidos);
418	        List<Fragmento> refragmentos =
419	            FusionDeHerramientas.combinar(
420	                reejecuciones.stream().map(Executor.EjecucionHerramienta::fragmentos).toList(),
421	                maxFragmentosContexto);
422	        UmbralRelevancia.Resultado umbralReformulado =
423	            UmbralRelevancia.evaluar(refragmentos, chunksProyecto, umbralRelevancia);
424	        // La reformulacion no siempre mejora: un LLM chico puede reformular mal y
425	        // alejarse del tema (medido en vivo: "que es un enum" -> una pregunta sobre
426	        // "estructuras de datos con acceso por indice numerico", sin relacion real).
427	        // Sin esta comparacion, una busqueda original ya buena (AMBIGUO con rerank
428	        // 5.35, candidata real: "enum Coin { PENNY(1)...") quedaba pisada sin mas
429	        // por la reformulada, mucho peor (INSUFICIENTE, rerank 0.2) -- se perdia una
430	        // respuesta que ya estaba bien encontrada. Se queda con lo que rinda mas.
431	        if (esMejor(umbralReformulado, umbral)) {
432	          ejecuciones = reejecuciones;
433	          fragmentos = refragmentos;
434	          umbral = umbralReformulado;
435	          consultaReformuladaParaMostrar = reformulacion.textoBusqueda();
436	        }
437	      }
438	    }
439	
440	    if (umbral.decision() == UmbralRelevancia.Decision.INSUFICIENTE) {
441	      return new PreSintesis(
442	          plan,
443	          ejecuciones,
444	          fragmentos,
445	          List.of(),
446	          "",
447	          MENSAJE_SIN_INFORMACION,
448	          consultaReformuladaParaMostrar,
449	          List.of(),
450	          inicio);
451	    }
452	
453	    // Etapa 5: expansion de contexto con secciones vecinas.
454	    String contexto = construirContexto(fragmentos);
455	    List<Cita> citas = fragmentos.stream().map(Citas::desde).toList();
456	
457	    if (umbral.decision() == UmbralRelevancia.Decision.AMBIGUO) {
458	      VerificadorGrounding.Veredicto veredicto =
459	          verificadorGrounding.verificar(pregunta.texto(), contexto);
460	      if (!veredicto.respondeLaPregunta()) {
461	        return new PreSintesis(
462	            plan,
463	            ejecuciones,
464	            fragmentos,
465	            List.of(),
466	            "",
467	            MENSAJE_SIN_INFORMACION,
468	            consultaReformuladaParaMostrar,
469	            List.of(),
470	            inicio);
471	      }
472	    }
473	
474	    return new PreSintesis(
475	        plan,
476	        ejecuciones,
477	        fragmentos,
478	        citas,
479	        contexto,
480	        null,
481	        consultaReformuladaParaMostrar,
482	        List.of(),
483	        inicio);
484	  }
