1	package co.g3a.baseconocimiento.orquestacion;
2	
3	import co.g3a.baseconocimiento.compartido.Dominio.Fragmento;
4	import java.util.List;
5	import java.util.Objects;
6	
7	/**
8	 * ADR-0008: la puerta de relevancia antes de sintetizar, en la etapa 4 del pipeline (después de
9	 * {@link FusionDeHerramientas}, antes de expandir contexto). Reemplaza la confianza ciega en que el
10	 * LLM reconozca por su cuenta que el contexto no alcanza — probado con {@code gemma3:4b} y {@code
11	 * granite4.1:3b}, ninguno lo hizo de forma confiable cuando el contexto es tangencial en vez de
12	 * vacío (ver ADR-0008 para la traza completa) — por una decisión determinista sobre el score del
13	 * cross-encoder.
14	 *
15	 * <p>Solo mira fragmentos que de verdad vienen de una búsqueda por relevancia ({@code rerank !=
16	 * null}). Las herramientas de listado directo ({@code recent_commits}, {@code subsystem_index},
17	 * {@code who_knows}) no rankean por relevancia a la consulta — su propia elección por el planner ya
18	 * es la señal — así que su presencia entre los fragmentos deja pasar la respuesta sin más:
19	 * forzarlas por este umbral las bloquearía siempre, porque nunca traen puntaje de reranker.
20	 *
21	 * <p>El piso de rechazo crece con el tamaño del corpus del proyecto (interpolación lineal entre
22	 * {@code piso} y {@code techo} sobre {@code chunksReferencia}): con pocos chunks — el corpus
23	 * semilla del taller, ~4 — los puntajes del cross-encoder se comprimen cerca de cero incluso para
24	 * una coincidencia real, así que empezar exigiendo {@code techo} bloquearía también las respuestas
25	 * buenas. Es una aproximación heurística sin más validación que la de ADR-0008 — no una curva
26	 * calibrada con datos de producción.
27	 *
28	 * <p>Por encima de ese piso, un solo score no alcanza a distinguir "relevante de verdad" de
29	 * "comparte vocabulario superficial" — ADR-0008 documenta un contraejemplo real donde una pregunta
30	 * irrelevante puntuó más alto que una relevante. Por eso el resultado tiene un tercer estado,
31	 * {@code AMBIGUO}: ni se rechaza ni se acepta solo con el score, se manda a {@code
32	 * VerificadorGrounding} para una segunda opinión antes de sintetizar. Solo se salta esa
33	 * verificación cuando el score supera {@code techoConfianza} — prácticamente una copia literal,
34	 * donde no hay ambigüedad real que resolver.
35	 */
36	final class UmbralRelevancia {
37	
38	  private UmbralRelevancia() {}
39	
40	  enum Decision {
41	    SUFICIENTE,
42	    AMBIGUO,
43	    INSUFICIENTE
44	  }
45	
46	  record Resultado(Decision decision, double umbralUsado, Double mejorPuntaje) {}
47	
48	  static double umbralEfectivo(long chunksProyecto, UmbralRelevanciaPropiedades props) {
49	    double proporcion =
50	        Math.min(1.0, chunksProyecto / (double) Math.max(1, props.chunksReferencia()));
51	    return props.piso() + (props.techo() - props.piso()) * proporcion;
52	  }
53	
54	  static Resultado evaluar(
55	      List<Fragmento> fragmentos, long chunksProyecto, UmbralRelevanciaPropiedades props) {
56	    if (!props.habilitado()) {
57	      return new Resultado(Decision.SUFICIENTE, 0.0, null);
58	    }
59	
60	    List<Double> puntajesRankeados =
61	        fragmentos.stream().map(Fragmento::rerank).filter(Objects::nonNull).toList();
62	    boolean hayFragmentosSinRankear = fragmentos.size() > puntajesRankeados.size();
63	    if (hayFragmentosSinRankear) {
64	      return new Resultado(Decision.SUFICIENTE, 0.0, null);
65	    }
66	
67	    double umbral = umbralEfectivo(chunksProyecto, props);
68	    if (puntajesRankeados.isEmpty()) {
69	      return new Resultado(Decision.INSUFICIENTE, umbral, null);
70	    }
71	
72	    double mejor = puntajesRankeados.stream().mapToDouble(Double::doubleValue).max().orElseThrow();
73	    if (mejor < umbral) {
74	      return new Resultado(Decision.INSUFICIENTE, umbral, mejor);
75	    }
76	    if (mejor >= props.techoConfianza()) {
77	      return new Resultado(Decision.SUFICIENTE, umbral, mejor);
78	    }
79	    return new Resultado(Decision.AMBIGUO, umbral, mejor);
80	  }
81	}
