25	/**
26	 * Las siete etapas de F3, conectadas: planificar, ejecutar herramientas en paralelo, fusionar entre
27	 * ellas, expandir contexto, sintetizar y registrar.
28	 *
29	 * <p>Las etapas 1 a 5 (todo lo anterior a la síntesis) son las mismas sin importar si el resultado
30	 * final es bloqueante o en streaming — por eso {@code prepararHastaContexto} existe: {@link
31	 * #ejecutar} (F3, para {@code /api/ask}) y {@link #ejecutarEnStreaming} (F4, para el SSE del
32	 * adaptador web) comparten esa preparación y solo difieren en cómo consumen el {@link Flux} del
33	 * {@link Sintetizador}.
34	 *
35	 * <p>No implementa {@link Consultar} directamente — {@link Consultador} es esa fachada mínima. Esta
36	 * clase devuelve la traza completa de las siete etapas porque {@code OrquestacionController} la
37	 * necesita entera para el criterio de salida de F3; los adaptadores de F4/F5 no deberían ver nada
38	 * de esto.
39	 */
40	@Component
41	class Orquestador {
42	
43	  /**
44	   * ADR-0008: lo que se responde cuando {@link UmbralRelevancia} decide que el mejor fragmento no
45	   * alcanza — en vez de dejar que el sintetizador improvise sobre contexto irrelevante.
46	   */
47	  static final String MENSAJE_SIN_INFORMACION =
48	      "No encontré información suficientemente relevante en la base de conocimiento "
49	          + "para responder esto. Prueba con otra formulación o verifica que el tema "
50	          + "esté cubierto por las fuentes ingeridas.";
51	
52	  /**
53	   * {@code prepararHastaContexto} es bloqueante de punta a punta (planificador, herramientas,
54	   * reformulador, verificador de grounding) y arranca ANTES de que exista ningún {@link Flux} — si
55	   * el cliente se desconecta a mitad de camino (un F5, cerrar la pestaña), no hay forma de que el
56	   * servidor se entere: la consulta sigue corriendo entera igual, gastando uno de los {@code
57	   * OLLAMA_NUM_PARALLEL} cupos de Ollama en un trabajo que nadie va a leer. Medido en vivo: esa
58	   * sola etapa tardó más de 4 minutos con Ministral 3B — de sobra para que una consulta nueva se
59	   * quede sin cupo detrás de una huérfana y termine mostrando "se perdió la conexión" sin ser ese
60	   * el problema real. Cancelar la huérfana a mitad de camino exigiría propagar la desconexión a
61	   * través de Planificador/Reformulador/VerificadorGrounding (varias clases, con cuidado real) —
62	   * como mitigación más simple, este semáforo evita que una consulta nueva SUME otra espera larga
63	   * encima: si no hay cupo, corta al toque con un mensaje claro en vez de competir.
64	   */
65	  static final String MENSAJE_SERVIDOR_OCUPADO =
66	      "El servidor ya está atendiendo el máximo de consultas al mismo tiempo. "
67	          + "Esperá un momento y volvé a intentarlo.";
68	
69	  /**
70	   * En modo {@link Consultar.ModoReformulacion.Proponer}, cuantas alternativas hacen falta para que
71	   * valga la pena preguntarle a la persona: con una sola no hay elección posible, y se responde de
72	   * inmediato con ella como en el modo automático.
73	   */
74	  static final int MIN_ALTERNATIVAS_PARA_ELEGIR = 2;
75	
76	  private final Planificador planificador;
77	  private final Reformulador reformulador;
78	  private final CatalogoHerramientas catalogo;
79	  private final Executor executor;
80	  private final ContextoRepositorio contextoRepo;
81	  private final HerramientasRepositorio herramientasRepo;
82	  private final Sintetizador sintetizador;
83	  private final VerificadorGrounding verificadorGrounding;
84	  private final QueryLogRepositorio queryLog;
85	  private final int maxFragmentosContexto;
86	  private final boolean expandirVecinos;
87	  private final UmbralRelevanciaPropiedades umbralRelevancia;
88	  private final Semaphore cupoConsultas;
89	  private final StreamsEnCursoRepositorio streamsEnCurso;
90	
91	  Orquestador(
92	      Planificador planificador,
93	      Reformulador reformulador,
94	      CatalogoHerramientas catalogo,
95	      Executor executor,
96	      ContextoRepositorio contextoRepo,
97	      HerramientasRepositorio herramientasRepo,
98	      Sintetizador sintetizador,
99	      VerificadorGrounding verificadorGrounding,
100	      QueryLogRepositorio queryLog,
101	      @Value("${kb.orquestacion.max-fragmentos-contexto:10}") int maxFragmentosContexto,
102	      @Value("${kb.orquestacion.expandir-vecinos:true}") boolean expandirVecinos,
103	      UmbralRelevanciaPropiedades umbralRelevancia,
104	      // Default 2 = OLLAMA_NUM_PARALLEL por defecto (compose.yml): no tiene
105	      // sentido admitir mas consultas reales en simultaneo que las que Ollama
106	      // puede atender a la vez.
107	      @Value("${kb.orquestacion.max-consultas-concurrentes:2}") int maxConsultasConcurrentes,
108	      StreamsEnCursoRepositorio streamsEnCurso) {
109	    this.planificador = planificador;
110	    this.reformulador = reformulador;
111	    this.catalogo = catalogo;
112	    this.executor = executor;
113	    this.contextoRepo = contextoRepo;
114	    this.herramientasRepo = herramientasRepo;
115	    this.sintetizador = sintetizador;
116	    this.verificadorGrounding = verificadorGrounding;
117	    this.queryLog = queryLog;
118	    this.maxFragmentosContexto = maxFragmentosContexto;
119	    this.expandirVecinos = expandirVecinos;
120	    this.umbralRelevancia = umbralRelevancia;
121	    this.cupoConsultas = new Semaphore(maxConsultasConcurrentes);
122	    this.streamsEnCurso = streamsEnCurso;
123	  }
124	
125	  record EjecucionPipeline(
126	      PlanDeHerramientas plan,
127	      List<Executor.EjecucionHerramienta> herramientas,
128	      List<Fragmento> fragmentosUsados,
129	      Respuesta respuesta,
130	      long queryLogId) {}
131	
132	  /**
133	   * Todo lo que las etapas 1-5 producen, listo para que la síntesis (etapa 6) lo consuma. {@code
134	   * respuestaFija} no nulo (ADR-0008) significa que la etapa 4 decidió que el contexto no alcanza:
135	   * la síntesis se salta por completo y ese texto es la respuesta. {@code
136	   * reformulacionesPropuestas} no vacía (solo con {@link Consultar.ModoReformulacion.Proponer})
137	   * significa que la etapa 4 se detuvo a esperar que la persona elija: no hay síntesis ni
138	   * respuesta.
139	   */
140	  private record PreSintesis(
141	      PlanDeHerramientas plan,
142	      List<Executor.EjecucionHerramienta> ejecuciones,
143	      List<Fragmento> fragmentos,
144	      List<Cita> citas,
145	      String contexto,
146	      String respuestaFija,
147	      String consultaReformulada,
148	      List<String> reformulacionesPropuestas,
149	      long inicioNanos) {}
150	
151	  /**
152	   * Bloqueante: espera a que la síntesis termine antes de devolver nada. Usado por {@code /api/ask}
153	   * y Teams — siempre con {@link Consultar.Preferencias#POR_DEFECTO}, porque ninguno de los dos
154	   * tiene cómo pedirle a la persona que elija algo a mitad de camino.
155	   */
156	  EjecucionPipeline ejecutar(Pregunta pregunta, ProyectoId proyecto, Filtros filtros) {
157	    boolean cupoAdquirido = cupoConsultas.tryAcquire();
158	    try {
159	      PreSintesis pre =
160	          cupoAdquirido
161	              ? prepararHastaContexto(
162	                  pregunta, proyecto, filtros, Consultar.Preferencias.POR_DEFECTO.reformulacion())
163	              : respuestaServidorOcupado();
164	
165	      // Etapa 6: sintesis en streaming, coleccionada aqui porque este metodo
166	      // devuelve una respuesta completa, no un Flux.
167	      String textoRespuesta =
168	          sintetizarBloqueante(pregunta, pre, Consultar.Preferencias.POR_DEFECTO.idioma());
169	
170	      long latenciaMs = (System.nanoTime() - pre.inicioNanos()) / 1_000_000;
171	      // advertencias queda vacio a proposito: el prompt de sintesis exige señalar
172	      // contradicciones EN el texto de la respuesta (con [n] y prosa), no en un
173	      // campo estructurado aparte -- eso pediria una segunda llamada al LLM solo
174	      // para separar "respuesta" de "advertencia", en contra de que la sintesis
175	      // sea en streaming.
176	      Respuesta respuesta =
177	          new Respuesta(
178	              textoRespuesta, pre.citas(), List.of(), latenciaMs, pre.consultaReformulada());
179	
180	      // Etapa 7: registrar.
181	      long queryLogId =
182	          queryLog.registrar(
183	              pregunta.texto(),
184	              proyecto.valor(),
185	              pre.plan(),
186	              pre.ejecuciones(),
187	              pre.fragmentos(),
188	              textoRespuesta,
189	              pre.citas(),
190	              latenciaMs);
191	
192	      return new EjecucionPipeline(
193	          pre.plan(), pre.ejecuciones(), pre.fragmentos(), respuesta, queryLogId);
194	    } finally {
195	      if (cupoAdquirido) {
196	        cupoConsultas.release();
197	      }
198	    }
199	  }
200	
201	  /**
202	   * En streaming: las citas de la etapa 5 vuelven de inmediato; el texto de la etapa 6 llega token
203	   * a token. El registro de la etapa 7 ocurre cuando el {@link Flux} completa, no antes — por eso
204	   * acumula el texto en un {@link StringBuilder} con {@code doOnNext} en vez de esperar a que el
205	   * llamador termine de consumirlo.
206	   */
207	  Consultar.RespuestaEnStreaming ejecutarEnStreaming(
208	      Pregunta pregunta,
209	      ProyectoId proyecto,
210	      Filtros filtros,
211	      Long conversacionId,
212	      Consultar.Preferencias preferencias) {
213	    // Antes que nada: si esta pagina se recarga al toque de preguntar, que
214	    // ya haya algo que encontrar via StreamsEnCursoRepositorio.buscar().
215	    if (conversacionId != null) {
216	      streamsEnCurso.iniciar(conversacionId, pregunta.texto(), proyecto.valor());
217	    }
218	
219	    boolean cupoAdquirido = cupoConsultas.tryAcquire();
220	    PreSintesis pre =
221	        cupoAdquirido
222	            ? prepararHastaContexto(pregunta, proyecto, filtros, preferencias.reformulacion())
223	            : respuestaServidorOcupado();
224	
225	    // Modo Proponer y la busqueda original no alcanzo: no hay nada que
226	    // sintetizar todavia. Se devuelven las alternativas y se suelta todo lo
227	    // que la consulta tenia tomado -- el cupo (no hay Flux cuyo doFinally lo
228	    // libere) y la fila de streams_en_curso (no hay respuesta que reconectar;
229	    // ver StreamsEnCursoRepositorio.descartar). Nada va a query_log: no se
230	    // respondio nada.
231	    if (!pre.reformulacionesPropuestas().isEmpty()) {
232	      if (cupoAdquirido) {
233	        cupoConsultas.release();
234	      }
235	      if (conversacionId != null) {
236	        streamsEnCurso.descartar(conversacionId);
237	      }
238	      return new Consultar.RespuestaEnStreaming(
239	          List.of(), Flux.empty(), null, Mono.empty(), pre.reformulacionesPropuestas());
240	    }
241	
242	    if (conversacionId != null) {
243	      streamsEnCurso.actualizarCitas(conversacionId, pre.citas(), pre.consultaReformulada());
244	    }
245	
246	    StringBuilder acumulado = new StringBuilder();
247	    // Se llena dentro del doOnComplete de abajo, cuando queryLog.registrar(...)
248	    // ya devolvio el id -- para TODO camino que complete, incluido "servidor
249	    // ocupado"/"sin informacion" (esos tambien escriben una fila real en
250	    // query_log). Queda en null si el Flux termina en error o se cancela: ahi
251	    // nunca se llega a escribir en query_log, no hay id que dar.
252	    AtomicReference<Long> queryLogIdHolder = new AtomicReference<>();
253	    Flux<String> textoBase =
254	        pre.respuestaFija() != null
255	            ? Flux.just(pre.respuestaFija())
256	            : sintetizador.sintetizar(pregunta.texto(), pre.contexto(), preferencias.idioma());
257	    Flux<String> texto =
258	        textoBase
259	            .doOnNext(acumulado::append)
260	            .doOnComplete(
261	                () -> {
262	                  long latenciaMs = (System.nanoTime() - pre.inicioNanos()) / 1_000_000;
263	                  long queryLogId =
264	                      queryLog.registrar(
265	                          pregunta.texto(),
266	                          proyecto.valor(),
267	                          pre.plan(),
268	                          pre.ejecuciones(),
269	                          pre.fragmentos(),
270	                          acumulado.toString(),
271	                          pre.citas(),
272	                          latenciaMs);
273	                  queryLogIdHolder.set(queryLogId);
274	                })
275	            // El cupo cubre TODA la consulta, no solo prepararHastaContexto: la
276	            // sintesis tambien le pide tokens a Ollama. Se libera aca, cuando el
277	            // Flux de verdad termina (completa, falla o el cliente se desconecta),
278	            // no antes -- doFinally cubre las tres formas de terminar. Mismo
279	            // razonamiento para dejar el resultado final en streams_en_curso: pasa
280	            // lo mismo haya o no alguien todavia escuchando del otro lado.
281	            .doFinally(
282	                signal -> {
283	                  if (cupoAdquirido) {
284	                    cupoConsultas.release();
285	                  }
286	                  if (conversacionId != null) {
