486	  /**
487	   * Cuántos fragmentos de la primera ronda se le muestran al Reformulador, y cuánto de cada uno.
488	   */
489	  static final int MAX_PISTAS = 5;
490	
491	  static final int LARGO_PISTA = 200;
492	
493	  /**
494	   * Una línea por fragmento: título y el comienzo del texto, aplanado. Acotado a {@link
495	   * #MAX_PISTAS} por {@link #LARGO_PISTA} caracteres para que quepa de sobra en el contexto del
496	   * reformulador (unos 300 tokens) sin desplazar al prompt de sistema.
497	   */
498	  static List<String> pistasDelCorpus(List<Fragmento> fragmentos) {
499	    return fragmentos.stream()
500	        .limit(MAX_PISTAS)
501	        .map(
502	            f -> {
503	              String texto = f.texto() == null ? "" : f.texto().replaceAll("\\s+", " ").strip();
504	              if (texto.length() > LARGO_PISTA) {
505	                texto = texto.substring(0, LARGO_PISTA) + "…";
506	              }
507	              return "[" + Citas.tituloDe(f) + "] " + texto;
508	            })
509	        .toList();
510	  }
511	
512	  /**
513	   * Compara dos rondas de búsqueda por qué tan bien pasan la puerta de relevancia: primero por
514	   * {@code Decision} (SUFICIENTE > AMBIGUO > INSUFICIENTE), y a igual decisión, por el mejor score
515	   * del reranker.
516	   */
517	  private static boolean esMejor(
518	      UmbralRelevancia.Resultado candidato, UmbralRelevancia.Resultado base) {
519	    int rangoCandidato = rangoDecision(candidato.decision());
520	    int rangoBase = rangoDecision(base.decision());
521	    if (rangoCandidato != rangoBase) {
522	      return rangoCandidato > rangoBase;
523	    }
524	    double puntajeCandidato =
525	        candidato.mejorPuntaje() == null ? Double.NEGATIVE_INFINITY : candidato.mejorPuntaje();
526	    double puntajeBase =
527	        base.mejorPuntaje() == null ? Double.NEGATIVE_INFINITY : base.mejorPuntaje();
528	    return puntajeCandidato > puntajeBase;
529	  }
530	
531	  private static int rangoDecision(UmbralRelevancia.Decision decision) {
532	    return switch (decision) {
533	      case SUFICIENTE -> 2;
534	      case AMBIGUO -> 1;
535	      case INSUFICIENTE -> 0;
536	    };
537	  }
538	
539	  /**
540	   * {@code kb.orquestacion.expandir-vecinos=false} (perfil Bonsai) apaga la expansión: cada
541	   * fragmento cuesta hasta 3x menos tokens sin sus vecinos, lo que permite subir {@code
542	   * max-fragmentos-contexto} y que sobrevivan más candidatos distintos dentro del mismo presupuesto
543	   * de contexto — medido en vivo: con contexto de 4096 tokens, 2 fragmentos CON vecinos ocupaban el
544	   * mismo espacio que varios más SIN vecinos, y el candidato relevante quedaba afuera cuando no
545	   * rankeaba entre los 2 primeros.
546	   */
547	  private String construirContexto(List<Fragmento> fragmentos) {
548	    StringBuilder contexto = new StringBuilder();
549	    for (int i = 0; i < fragmentos.size(); i++) {
550	      Fragmento f = fragmentos.get(i);
551	      contexto.append("[%d] %s (%s)\n".formatted(i + 1, Citas.tituloDe(f), f.uri()));
552	
553	      if (expandirVecinos) {
554	        List<ContextoRepositorio.Vecino> vecinos = contextoRepo.vecinos(f.documentoId(), f.ord());
555	        vecinos.stream()
556	            .filter(v -> v.ord() < f.ord())
557	            .forEach(v -> contexto.append(v.texto()).append('\n'));
558	        contexto.append(f.texto()).append('\n');
559	        vecinos.stream()
560	            .filter(v -> v.ord() > f.ord())
561	            .forEach(v -> contexto.append(v.texto()).append('\n'));
562	      } else {
563	        contexto.append(f.texto()).append('\n');
564	      }
565	
566	      contexto.append('\n');
567	    }
568	    return contexto.toString();
569	  }
570	}
