1	// Registra el acta de la sesion EN CURSO, para commitearla (#222, fase 3), desde la raiz del repo:
2	//
3	//   node $ACTA/registrar-sesion.mjs [--sesion <id>] [--sin-stage]
4	//
5	// El hook compila el acta al cerrar la sesion, pero el commit que la cita se hace antes, durante
6	// la sesion. Este script compila lo que va de ella, la cura, empaca sus objetos, reescribe el
7	// indice y deja en stage, con `git add -f`, los archivos del acta de la tarea de la rama actual:
8	// la cruda, la curada, el pack de objetos y el indice. .ia/ sigue en .gitignore a proposito: asi
9	// un `git add -A` no publica todas las sesiones, solo la que se registra.
10	//
11	// La sesion es la de CLAUDE_CODE_SESSION_ID, que Claude Code exporta a los comandos (verificado
12	// con 2.1.287), o la de --sesion. El transcript se busca en ~/.claude/projects/*/<id>.jsonl.
13	//
14	// La llamada en curso, la que corre este script, todavia no tiene resultado: el transcript y la
15	// captura se cortan justo antes de ella. Sin el corte, la curada se detendria en una accion sin
16	// arbol de despues. Al cerrar la sesion, el hook vuelve a compilar el acta entera; la que se
17	// commiteo queda como estaba hasta el proximo registro.
18	//
19	// Codigos de salida: 0 registrada, 1 la compilacion o la curacion no salieron, 2 uso incorrecto.
20	import { spawnSync } from 'node:child_process';
21	import crypto from 'node:crypto';
22	import fs from 'node:fs';
23	import os from 'node:os';
24	import path from 'node:path';
25	import { fileURLToPath } from 'node:url';
26	import { compilarYCerrar, rutaHermana } from './cerrar-acta.mjs';
27	import { archivoDeEvidencia, leerCaptura, tareaDeRama } from './compilar-acta.mjs';
28	import { git, raizDelRepo } from './git.mjs';
29	
30	export function buscarTranscript(sesion, proyectos = path.join(os.homedir(), '.claude',
31	  'projects')) {
32	  if (!fs.existsSync(proyectos)) return null;
33	  for (const d of fs.readdirSync(proyectos).sort()) {
34	    const t = path.join(proyectos, d, `${sesion}.jsonl`);
35	    if (fs.existsSync(t)) return t;
36	  }
37	  return null;
38	}
39	
40	// Copia el transcript y la captura hasta antes de la ultima llamada sin resultado. Devuelve las
41	// rutas de las copias y el id de la llamada cortada (null si no habia ninguna).
42	export function cortarEnCurso({ transcript, captura, destino }) {
43	  const lineas = fs.readFileSync(transcript, 'utf8').split('\n');
44	  const conResultado = new Set();
45	  for (const l of lineas) {
46	    if (!l.includes('tool_result')) continue;
47	    try {
48	      for (const b of JSON.parse(l).message?.content || []) {
49	        if (b.type === 'tool_result') conResultado.add(b.tool_use_id);
50	      }
51	    } catch { /* una linea rota la ignora el compilador */ }
52	  }
53	  let corte = lineas.length;
54	  let enCurso = null;
55	  // La ULTIMA llamada sin resultado: una interrumpida mas atras tambien puede no tenerlo, y cortar
56	  // ahi perderia el resto de la sesion.
57	  lineas.forEach((l, i) => {
58	    if (!l.includes('tool_use')) return;
59	    try {
60	      const o = JSON.parse(l);
61	      if (o.isSidechain || o.type !== 'assistant') return;
62	      const uso = (o.message?.content || []).find((b) => b.type === 'tool_use' &&
63	        !conResultado.has(b.id));
64	      if (uso) {
65	        enCurso = uso.id;
66	        corte = i;
67	      }
68	    } catch { /* idem */ }
69	  });
70	  fs.mkdirSync(destino, { recursive: true });
71	  const t = path.join(destino, path.basename(transcript));
72	  fs.writeFileSync(t, lineas.slice(0, corte).join('\n') + '\n');
73	  const eventos = leerCaptura(captura);
74	  const hasta = enCurso ? eventos.findIndex((e) => e.toolUseId === enCurso) : -1;
75	  const c = path.join(destino, 'captura.jsonl');
76	  fs.writeFileSync(c, (hasta === -1 ? eventos : eventos.slice(0, hasta))
77	    .map((e) => JSON.stringify(e)).join('\n') + '\n');
78	  return { transcript: t, captura: c, enCurso };
79	}
80	
81	// El plan del issue de la tarea, tal como estaba al registrar (#230): es el instructivo de trabajo
82	// de una sesion que trabaja el issue sin una skill. Se guarda junto al acta con la fecha de su
83	// ultima edicion y el sha256 de su texto, y se versiona con ella. Sin red o sin issue, no se
84	// guarda y la conformidad lo dice.
85	// Las capturas y los trace incluidos en el acta (#230, frente 3): van en stage con ella.
86	export function evidenciasDe(cruda) {
87	  const carpeta = path.join(path.dirname(cruda), 'evidencias');
88	  const rutas = new Set();
89	  for (const linea of fs.readFileSync(cruda, 'utf8').split('\n')) {
90	    if (!linea.includes('"evidencias"')) continue;
91	    for (const e of JSON.parse(linea).evidencias || []) {
92	      if (e.incluida) rutas.add(path.join(carpeta, archivoDeEvidencia(e)));
93	    }
94	  }
95	  return [...rutas];
96	}
97	
98	export function leerIssueDeGitHub(numero) {
99	  const campos = 'number,title,body,updatedAt';
100	  const r = spawnSync('gh', ['issue', 'view', String(numero), '--json', campos],
101	    { encoding: 'utf8', timeout: 20000 });
102	  if (r.status !== 0) return null;
103	  try {
104	    return JSON.parse(r.stdout);
105	  } catch {
106	    return null;
107	  }
108	}
109	
110	export function guardarPlanDelIssue({ carpeta, tarea, leerIssue = leerIssueDeGitHub }) {
111	  if (!/^\d+$/.test(tarea)) return null;
112	  const issue = leerIssue(tarea);
113	  if (!issue?.body) return null;
114	  const cuerpo = issue.body.replace(/\r\n/g, '\n');
115	  const plan = { numero: Number(tarea), titulo: issue.title, actualizado: issue.updatedAt,
116	    sha256: crypto.createHash('sha256').update(cuerpo).digest('hex'), cuerpo };
117	  const destino = path.join(carpeta, 'plan-del-issue.json');
118	  fs.writeFileSync(destino, JSON.stringify(plan, null, 2) + '\n');
119	  return destino;
120	}
121	
122	export function registrar({ sesion, raizRepo, stage = true, log = console, proyectos,
123	  leerIssue = leerIssueDeGitHub }) {
124	  const transcript = buscarTranscript(sesion, proyectos);
125	  if (!transcript) {
126	    log.error(`No encuentro el transcript de la sesion ${sesion} en ~/.claude/projects.`);
127	    return { codigo: 1, archivos: [] };
128	  }
129	  const destino = fs.mkdtempSync(path.join(os.tmpdir(), 'acta-registro-'));
130	  try {
131	    const cortado = cortarEnCurso({ transcript, destino,
132	      captura: path.join(raizRepo, '.ia', 'captura', `${sesion}.jsonl`) });
133	    const { codigo, escritas } = compilarYCerrar({ transcript: cortado.transcript,
134	      captura: cortado.captura, raizRepo, log, carpetaSesion: transcript.replace(/\.jsonl$/, '') });
135	    const rama = git(['rev-parse', '--abbrev-ref', 'HEAD'], { cwd: raizRepo }).trim();
136	    const tarea = tareaDeRama(rama);
137	    const cruda = escritas.find((e) => path.basename(path.dirname(e)) === tarea);
138	    if (!cruda) {
139	      log.error(`La sesion no escribio un acta para la tarea ${tarea} (rama ${rama}).`);
140	      return { codigo: 1, archivos: [] };
141	    }
142	    if (!guardarPlanDelIssue({ carpeta: path.dirname(cruda), tarea, leerIssue })) {
143	      log.error(`No se guardo el plan del issue #${tarea}: sin red, sin gh o sin texto.`);
144	    }
145	    const archivos = [cruda, rutaHermana(cruda, '.acta.curada.jsonl'),
146	      rutaHermana(cruda, '.acta.objetos.pack'), path.join(path.dirname(cruda), 'indice.json'),
147	      path.join(path.dirname(cruda), 'plan-del-issue.json'), ...evidenciasDe(cruda)]
148	      .filter((f) => fs.existsSync(f)).map((f) => path.relative(raizRepo, f).replace(/\\/g, '/'));
149	    const curada = archivos.some((f) => f.endsWith('.acta.curada.jsonl'));
150	    if (stage) git(['add', '-f', '--', ...archivos], { cwd: raizRepo });
151	    for (const f of archivos) log.log(`${stage ? 'En stage' : 'Escrito'}: ${f}`);
152	    if (!curada) log.error('La curada no salio: el commit no puede citarla. Mira los avisos.');
153	    return { codigo: codigo === 0 && curada ? 0 : 1, archivos };
154	  } finally {
155	    fs.rmSync(destino, { recursive: true, force: true });
156	  }
157	}
158	
159	if (process.argv[1] === fileURLToPath(import.meta.url)) {
160	  const args = process.argv.slice(2);
161	  const i = args.indexOf('--sesion');
162	  const sesion = i === -1 ? process.env.CLAUDE_CODE_SESSION_ID : args[i + 1];
163	  const conocidos = new Set(['--sesion', '--sin-stage', sesion]);
164	  const raizRepo = raizDelRepo(process.cwd());
165	  if (!sesion || !raizRepo || args.some((a) => !conocidos.has(a))) {
166	    console.error('Uso: node $ACTA/registrar-sesion.mjs [--sesion <id>] [--sin-stage]');
167	    console.error('Sin --sesion, usa CLAUDE_CODE_SESSION_ID: corre dentro de Claude Code.');
168	    process.exitCode = 2;
169	  } else {
170	    process.exitCode = registrar({ sesion, raizRepo, stage: !args.includes('--sin-stage') })
171	      .codigo;
172	  }
