326	  private String sintetizarBloqueante(Pregunta pregunta, PreSintesis pre, IdiomaRespuesta idioma) {
327	    if (pre.respuestaFija() != null) {
328	      return pre.respuestaFija();
329	    }
330	    String texto =
331	        sintetizador
332	            .sintetizar(pregunta.texto(), pre.contexto(), idioma)
