339	  private PreSintesis prepararHastaContexto(
340	      Pregunta pregunta,
341	      ProyectoId proyecto,
342	      Filtros filtros,
343	      Consultar.ModoReformulacion modoReformulacion) {
344	    long inicio = System.nanoTime();
345	    List<Long> documentosPermitidos = filtros.documentosPermitidos();
346	
347	    // Etapa 1: planificar -- siempre sobre la pregunta original, aunque la
348	    // busqueda vaya con otro texto: el plan elige herramientas segun de que
349	    // trata la pregunta, y eso no cambia con la reformulacion.
350	    PlanDeHerramientas plan = planificador.planificar(pregunta.texto(), catalogo.descripciones());
351	
352	    // Con Elegida, la persona ya decidio con que texto buscar (puede ser la
353	    // propia pregunta, si prefirio no reformular): se busca con eso y no se
354	    // vuelve a pasar por el Reformulador -- si no, su eleccion quedaria pisada
355	    // en silencio por una reformulacion automatica.
356	    String consultaBusqueda = pregunta.texto();
357	    String consultaReformuladaParaMostrar = null;
358	    if (modoReformulacion instanceof Consultar.ModoReformulacion.Elegida elegida) {
359	      consultaBusqueda = elegida.consultaDeBusqueda();
360	      if (!consultaBusqueda.strip().equalsIgnoreCase(pregunta.texto().strip())) {
361	        consultaReformuladaParaMostrar = consultaBusqueda;
362	      }
363	    }
364	
365	    // Etapas 2-3: ejecutar herramientas en paralelo, con fallas aisladas por
366	    // herramienta.
367	    List<Executor.EjecucionHerramienta> ejecuciones =
368	        executor.ejecutar(plan.herramientas(), consultaBusqueda, proyecto, documentosPermitidos);
369	
370	    // Etapa 4: fusionar y deduplicar entre herramientas.
371	    List<Fragmento> fragmentos =
372	        FusionDeHerramientas.combinar(
373	            ejecuciones.stream().map(Executor.EjecucionHerramienta::fragmentos).toList(),
374	            maxFragmentosContexto);
375	
376	    // ADR-0008: puerta de relevancia antes de expandir contexto y sintetizar.
377	    // El score del cross-encoder decide los casos claros sin gastar una
378	    // llamada al LLM; la zona ambigua se manda a VerificadorGrounding en vez
379	    // de confiar en que el propio sintetizador se autocensure.
380	    long chunksProyecto = herramientasRepo.contarChunks(proyecto.valor());
381	    UmbralRelevancia.Resultado umbral =
382	        UmbralRelevancia.evaluar(fragmentos, chunksProyecto, umbralRelevancia);
383	
384	    // Reformula la consulta de busqueda SOLO cuando la busqueda con la pregunta tal cual
385	    // no llego a SUFICIENTE -- reformular siempre, incluso en las preguntas que ya
386	    // buscaban bien, sumaba una llamada al LLM de mas en cada pregunta sin necesidad
387	    // (hallazgos 70-71 de la investigacion de VRAM y modelo LLM confirmaron que ayuda en
388	    // el caso dificil sin romper el caso facil, pero median el costo de la llamada
389	    // incondicional). Cubre tanto INSUFICIENTE (el caso que motivo el componente, ver
390	    // hallazgo 63: "autoboxing" vs. "boxing conversion") como AMBIGUO -- en ambos el score
391	    // ya senala que el texto original no encontro un candidato fuerte.
392	    boolean puedeReformular =
393	        !(modoReformulacion instanceof Consultar.ModoReformulacion.Elegida)
394	            && umbral.decision() != UmbralRelevancia.Decision.SUFICIENTE;
395	    if (puedeReformular) {
396	      // Los fragmentos de la primera ronda, aunque no alcancen, ya son texto REAL
397	      // de la fuente: le muestran al Reformulador con que palabras y en que
398	      // idioma esta escrita, en vez de dejarlo adivinar (ver Reformulador).
399	      Reformulador.Reformulacion reformulacion =
400	          reformulador.reformular(pregunta.texto(), pistasDelCorpus(fragmentos));
401	      if (modoReformulacion instanceof Consultar.ModoReformulacion.Proponer
402	          && reformulacion.alternativas().size() >= MIN_ALTERNATIVAS_PARA_ELEGIR) {
403	        // La persona elige: se corta aca, sin gastar la segunda ronda de
404	        // herramientas ni la sintesis. Con una sola alternativa no hay nada
405	        // que elegir y se responde de inmediato por el camino automatico de
406	        // abajo (pedido explicito de producto); sin ninguna, tambien.
407	        return new PreSintesis(
408	            plan,
409	            ejecuciones,
410	            fragmentos,
411	            List.of(),
412	            "",
413	            null,
414	            null,
415	            reformulacion.alternativas(),
416	            inicio);
417	      }
418	      if (reformulacion.reformulada()) {
419	        List<Executor.EjecucionHerramienta> reejecuciones =
420	            executor.ejecutar(
421	                plan.herramientas(), reformulacion.textoBusqueda(), proyecto, documentosPermitidos);
422	        List<Fragmento> refragmentos =
423	            FusionDeHerramientas.combinar(
424	                reejecuciones.stream().map(Executor.EjecucionHerramienta::fragmentos).toList(),
425	                maxFragmentosContexto);
426	        UmbralRelevancia.Resultado umbralReformulado =
427	            UmbralRelevancia.evaluar(refragmentos, chunksProyecto, umbralRelevancia);
428	        // La reformulacion no siempre mejora: un LLM chico puede reformular mal y
429	        // alejarse del tema (medido en vivo: "que es un enum" -> una pregunta sobre
430	        // "estructuras de datos con acceso por indice numerico", sin relacion real).
431	        // Sin esta comparacion, una busqueda original ya buena (AMBIGUO con rerank
432	        // 5.35, candidata real: "enum Coin { PENNY(1)...") quedaba pisada sin mas
433	        // por la reformulada, mucho peor (INSUFICIENTE, rerank 0.2) -- se perdia una
434	        // respuesta que ya estaba bien encontrada. Se queda con lo que rinda mas.
435	        if (esMejor(umbralReformulado, umbral)) {
436	          ejecuciones = reejecuciones;
437	          fragmentos = refragmentos;
438	          umbral = umbralReformulado;
439	          consultaReformuladaParaMostrar = reformulacion.textoBusqueda();
440	        }
441	      }
442	    }
443	
444	    if (umbral.decision() == UmbralRelevancia.Decision.INSUFICIENTE) {
445	      return new PreSintesis(
446	          plan,
447	          ejecuciones,
448	          fragmentos,
449	          List.of(),
450	          "",
451	          MENSAJE_SIN_INFORMACION,
452	          consultaReformuladaParaMostrar,
453	          List.of(),
454	          inicio);
455	    }
456	
457	    // Etapa 5: expansion de contexto con secciones vecinas.
458	    String contexto = construirContexto(fragmentos);
459	    List<Cita> citas = fragmentos.stream().map(Citas::desde).toList();
460	
461	    if (umbral.decision() == UmbralRelevancia.Decision.AMBIGUO) {
462	      VerificadorGrounding.Veredicto veredicto =
463	          verificadorGrounding.verificar(pregunta.texto(), contexto);
464	      if (!veredicto.respondeLaPregunta()) {
465	        return new PreSintesis(
466	            plan,
467	            ejecuciones,
468	            fragmentos,
469	            List.of(),
470	            "",
471	            MENSAJE_SIN_INFORMACION,
472	            consultaReformuladaParaMostrar,
473	            List.of(),
474	            inicio);
475	      }
476	    }
477	
478	    return new PreSintesis(
479	        plan,
480	        ejecuciones,
481	        fragmentos,
482	        citas,
483	        contexto,
484	        null,
485	        consultaReformuladaParaMostrar,
486	        List.of(),
487	        inicio);
488	  }
