490	  /**
491	   * Cuántos fragmentos de la primera ronda se le muestran al Reformulador, y cuánto de cada uno.
492	   */
493	  static final int MAX_PISTAS = 5;
494	
495	  static final int LARGO_PISTA = 200;
496	
497	  /**
498	   * Una línea por fragmento: título y el comienzo del texto, aplanado. Acotado a {@link
499	   * #MAX_PISTAS} por {@link #LARGO_PISTA} caracteres para que quepa de sobra en el contexto del
500	   * reformulador (unos 300 tokens) sin desplazar al prompt de sistema.
501	   */
502	  static List<String> pistasDelCorpus(List<Fragmento> fragmentos) {
503	    return fragmentos.stream()
504	        .limit(MAX_PISTAS)
505	        .map(
506	            f -> {
507	              String texto = f.texto() == null ? "" : f.texto().replaceAll("\\s+", " ").strip();
508	              if (texto.length() > LARGO_PISTA) {
509	                texto = texto.substring(0, LARGO_PISTA) + "…";
510	              }
511	              return "[" + Citas.tituloDe(f) + "] " + texto;
512	            })
513	        .toList();
514	  }
515	
516	  /**
517	   * Compara dos rondas de búsqueda por qué tan bien pasan la puerta de relevancia: primero por
518	   * {@code Decision} (SUFICIENTE > AMBIGUO > INSUFICIENTE), y a igual decisión, por el mejor score
519	   * del reranker.
520	   */
521	  private static boolean esMejor(
522	      UmbralRelevancia.Resultado candidato, UmbralRelevancia.Resultado base) {
523	    int rangoCandidato = rangoDecision(candidato.decision());
524	    int rangoBase = rangoDecision(base.decision());
525	    if (rangoCandidato != rangoBase) {
526	      return rangoCandidato > rangoBase;
527	    }
528	    double puntajeCandidato =
529	        candidato.mejorPuntaje() == null ? Double.NEGATIVE_INFINITY : candidato.mejorPuntaje();
530	    double puntajeBase =
531	        base.mejorPuntaje() == null ? Double.NEGATIVE_INFINITY : base.mejorPuntaje();
532	    return puntajeCandidato > puntajeBase;
533	  }
534	
535	  private static int rangoDecision(UmbralRelevancia.Decision decision) {
536	    return switch (decision) {
537	      case SUFICIENTE -> 2;
538	      case AMBIGUO -> 1;
539	      case INSUFICIENTE -> 0;
540	    };
541	  }
542	
543	  /**
544	   * {@code kb.orquestacion.expandir-vecinos=false} (perfil Bonsai) apaga la expansión: cada
545	   * fragmento cuesta hasta 3x menos tokens sin sus vecinos, lo que permite subir {@code
546	   * max-fragmentos-contexto} y que sobrevivan más candidatos distintos dentro del mismo presupuesto
547	   * de contexto — medido en vivo: con contexto de 4096 tokens, 2 fragmentos CON vecinos ocupaban el
548	   * mismo espacio que varios más SIN vecinos, y el candidato relevante quedaba afuera cuando no
549	   * rankeaba entre los 2 primeros.
550	   */
551	  private String construirContexto(List<Fragmento> fragmentos) {
552	    StringBuilder contexto = new StringBuilder();
553	    for (int i = 0; i < fragmentos.size(); i++) {
554	      Fragmento f = fragmentos.get(i);
555	      contexto.append("[%d] %s (%s)\n".formatted(i + 1, Citas.tituloDe(f), f.uri()));
556	
557	      if (expandirVecinos) {
558	        List<ContextoRepositorio.Vecino> vecinos = contextoRepo.vecinos(f.documentoId(), f.ord());
559	        vecinos.stream()
560	            .filter(v -> v.ord() < f.ord())
561	            .forEach(v -> contexto.append(v.texto()).append('\n'));
562	        contexto.append(f.texto()).append('\n');
563	        vecinos.stream()
564	            .filter(v -> v.ord() > f.ord())
565	            .forEach(v -> contexto.append(v.texto()).append('\n'));
566	      } else {
567	        contexto.append(f.texto()).append('\n');
568	      }
569	
570	      contexto.append('\n');
571	    }
572	    return contexto.toString();
573	  }
574	}

