132	  /**
133	   * Todo lo que las etapas 1-5 producen, listo para que la síntesis (etapa 6) lo consuma. {@code
134	   * respuestaFija} no nulo (ADR-0008) significa que la etapa 4 decidió que el contexto no alcanza:
135	   * la síntesis se salta por completo y ese texto es la respuesta. {@code
136	   * reformulacionesPropuestas} no vacía (solo con {@link Consultar.ModoReformulacion.Proponer})
137	   * significa que la etapa 4 se detuvo a esperar que la persona elija: no hay síntesis ni
138	   * respuesta.
139	   */
140	  private record PreSintesis(
141	      PlanDeHerramientas plan,
142	      List<Executor.EjecucionHerramienta> ejecuciones,
143	      List<Fragmento> fragmentos,
144	      List<Cita> citas,
145	      String contexto,
146	      String respuestaFija,
147	      String consultaReformulada,
148	      List<String> reformulacionesPropuestas,
149	      long inicioNanos) {}
