151	  /**
152	   * Bloqueante: espera a que la síntesis termine antes de devolver nada. Usado por {@code /api/ask}
153	   * y Teams — siempre con {@link Consultar.Preferencias#POR_DEFECTO}, porque ninguno de los dos
154	   * tiene cómo pedirle a la persona que elija algo a mitad de camino.
155	   */
156	  EjecucionPipeline ejecutar(Pregunta pregunta, ProyectoId proyecto, Filtros filtros) {
157	    boolean cupoAdquirido = cupoConsultas.tryAcquire();
158	    try {
159	      PreSintesis pre =
160	          cupoAdquirido
161	              ? prepararHastaContexto(
162	                  pregunta, proyecto, filtros, Consultar.Preferencias.POR_DEFECTO.reformulacion())
163	              : respuestaServidorOcupado();
164	
165	      // Etapa 6: sintesis en streaming, coleccionada aqui porque este metodo
166	      // devuelve una respuesta completa, no un Flux.
167	      String textoRespuesta =
168	          sintetizarBloqueante(pregunta, pre, Consultar.Preferencias.POR_DEFECTO.idioma());
169	
170	      long latenciaMs = (System.nanoTime() - pre.inicioNanos()) / 1_000_000;
171	      // Las contradicciones NO van en advertencias: el prompt de sintesis exige
172	      // señalarlas EN el texto (con [n] y prosa); separarlas pediria una segunda
173	      // llamada al LLM. Lo que si va es lo determinista: una cita [n] fuera de
174	      // 1..k (issue #52). Con respuesta fija no hubo sintesis ni nada que validar.
175	      List<String> advertencias =
176	          pre.respuestaFija() != null
177	              ? List.of()
178	              : ValidadorDeCitas.advertencias(
179	                  ValidadorDeCitas.validar(textoRespuesta, pre.citas().size()));
180	      Respuesta respuesta =
181	          new Respuesta(
182	              textoRespuesta, pre.citas(), advertencias, latenciaMs, pre.consultaReformulada());
183	
184	      // Etapa 7: registrar.
185	      long queryLogId =
186	          queryLog.registrar(
187	              pregunta.texto(),
188	              proyecto.valor(),
189	              pre.plan(),
190	              pre.ejecuciones(),
191	              pre.fragmentos(),
192	              textoRespuesta,
193	              pre.citas(),
194	              latenciaMs);
195	
196	      return new EjecucionPipeline(
197	          pre.plan(), pre.ejecuciones(), pre.fragmentos(), respuesta, queryLogId);
198	    } finally {
199	      if (cupoAdquirido) {
200	        cupoConsultas.release();
201	      }
202	    }
203	  }
204	
205	  /**
206	   * En streaming: las citas de la etapa 5 vuelven de inmediato; el texto de la etapa 6 llega token
207	   * a token. El registro de la etapa 7 ocurre cuando el {@link Flux} completa, no antes — por eso
208	   * acumula el texto en un {@link StringBuilder} con {@code doOnNext} en vez de esperar a que el
209	   * llamador termine de consumirlo.
210	   */
211	  Consultar.RespuestaEnStreaming ejecutarEnStreaming(
212	      Pregunta pregunta,
213	      ProyectoId proyecto,
214	      Filtros filtros,
215	      Long conversacionId,
216	      Consultar.Preferencias preferencias) {
217	    // Antes que nada: si esta pagina se recarga al toque de preguntar, que
218	    // ya haya algo que encontrar via StreamsEnCursoRepositorio.buscar().
219	    if (conversacionId != null) {
220	      streamsEnCurso.iniciar(conversacionId, pregunta.texto(), proyecto.valor());
221	    }
222	
223	    boolean cupoAdquirido = cupoConsultas.tryAcquire();
224	    PreSintesis pre =
225	        cupoAdquirido
226	            ? prepararHastaContexto(pregunta, proyecto, filtros, preferencias.reformulacion())
227	            : respuestaServidorOcupado();
228	
229	    // Modo Proponer y la busqueda original no alcanzo: no hay nada que
230	    // sintetizar todavia. Se devuelven las alternativas y se suelta todo lo
231	    // que la consulta tenia tomado -- el cupo (no hay Flux cuyo doFinally lo
232	    // libere) y la fila de streams_en_curso (no hay respuesta que reconectar;
233	    // ver StreamsEnCursoRepositorio.descartar). Nada va a query_log: no se
234	    // respondio nada.
235	    if (!pre.reformulacionesPropuestas().isEmpty()) {
236	      if (cupoAdquirido) {
237	        cupoConsultas.release();
238	      }
239	      if (conversacionId != null) {
240	        streamsEnCurso.descartar(conversacionId);
241	      }
242	      return new Consultar.RespuestaEnStreaming(
243	          List.of(), Flux.empty(), null, Mono.empty(), pre.reformulacionesPropuestas());
244	    }
245	
246	    if (conversacionId != null) {
247	      streamsEnCurso.actualizarCitas(conversacionId, pre.citas(), pre.consultaReformulada());
248	    }
249	
250	    StringBuilder acumulado = new StringBuilder();
251	    // Se llena dentro del doOnComplete de abajo, cuando queryLog.registrar(...)
252	    // ya devolvio el id -- para TODO camino que complete, incluido "servidor
253	    // ocupado"/"sin informacion" (esos tambien escriben una fila real en
254	    // query_log). Queda en null si el Flux termina en error o se cancela: ahi
255	    // nunca se llega a escribir en query_log, no hay id que dar.
256	    AtomicReference<Long> queryLogIdHolder = new AtomicReference<>();
257	    Flux<String> textoBase =
258	        pre.respuestaFija() != null
259	            ? Flux.just(pre.respuestaFija())
260	            : sintetizador.sintetizar(pregunta.texto(), pre.contexto(), preferencias.idioma());
261	    Flux<String> texto =
262	        textoBase
263	            .doOnNext(acumulado::append)
264	            .doOnComplete(
265	                () -> {
266	                  long latenciaMs = (System.nanoTime() - pre.inicioNanos()) / 1_000_000;
267	                  long queryLogId =
268	                      queryLog.registrar(
269	                          pregunta.texto(),
270	                          proyecto.valor(),
271	                          pre.plan(),
272	                          pre.ejecuciones(),
273	                          pre.fragmentos(),
274	                          acumulado.toString(),
275	                          pre.citas(),
276	                          latenciaMs);
277	                  queryLogIdHolder.set(queryLogId);
278	                })
279	            // El cupo cubre TODA la consulta, no solo prepararHastaContexto: la
280	            // sintesis tambien le pide tokens a Ollama. Se libera aca, cuando el
281	            // Flux de verdad termina (completa, falla o el cliente se desconecta),
282	            // no antes -- doFinally cubre las tres formas de terminar. Mismo
283	            // razonamiento para dejar el resultado final en streams_en_curso: pasa
284	            // lo mismo haya o no alguien todavia escuchando del otro lado.
285	            .doFinally(
286	                signal -> {
287	                  if (cupoAdquirido) {
288	                    cupoConsultas.release();
289	                  }
290	                  if (conversacionId != null) {
291	                    String estadoFinal = signal == SignalType.ON_COMPLETE ? "completo" : "error";
292	                    streamsEnCurso.finalizar(
293	                        conversacionId, estadoFinal, acumulado.toString(), queryLogIdHolder.get());
294	                  }
295	                });
296	
297	    // Mono.fromSupplier, no un valor ya calculado: se lee recien cuando alguien
298	    // lo suscribe (ChatController lo hace despues de agotar `texto` dentro del
299	    // mismo Flux.concat), momento en el que el doOnComplete de arriba ya corrio
300	    // y el holder tiene el id real.
301	    Mono<Long> queryLogId = Mono.fromSupplier(queryLogIdHolder::get);
302	    return new Consultar.RespuestaEnStreaming(
303	        pre.citas(), texto, pre.consultaReformulada(), queryLogId, List.of());
304	  }
